with flattened as (select id, customer_id, created_at, coupon_codes, item.product_id, item.qty, item.price, item.promo from (select id, customer_id, created_at, coupon_codes, explode_outer(items) as item from carts) t), with_windows as (select *, stddev_samp(price) over (partition by promo) promo_stddev_samp_price, cume_dist() over (partition by customer_id, promo order by product_id desc nulls last) product_id_cume_dist, count(product_id) over (partition by promo, customer_id order by cast(created_at as bigint) asc range between 3600 preceding and current row) product_id_count_1h from flattened where customer_id = 31), valid as (select *, trim(promo) clean_promo, round(product_id_cume_dist, 0) product_id_cume_dist_rounded, coalesce(promo, 'UNKNOWN') resolved_promo from with_windows where product_id_cume_dist >= 0.27 and created_at > timestamp '2025-03-01 15:00:00'), with_dims as (select a.customer_id, a.created_at, a.coupon_codes, a.price, a.promo_stddev_samp_price, a.product_id_cume_dist, a.product_id_count_1h, a.product_id_cume_dist_rounded, d.email, d.country from valid a left join customers d on a.customer_id = d.id), enriched as (select a.*, d.age from with_dims a inner join customers d on a.customer_id <=> d.id), enriched_carts as (select src.*, d.email as customer_email from enriched src left join customers d on src.customer_id = d.id), filtered as (select *, case when country = 'US' then 1 else 0 end is_us, coalesce(country, 'DIRECT') country_clean from enriched_carts where created_at >= timestamp '2025-03-01 22:00:00') select * from (select customer_id, country, is_us from filtered) src pivot (max(is_us) as value_sum, count(1) as n for country in ('TH', 'JP'));
